const $=s=>document.querySelector(s);
const prizes=[{name:'旅行手账本',image:'assets/journal.png'},{name:'薯队长抱枕',image:'assets/pillow.png'},{name:'大疆 Pocket 2',image:'assets/camera.png'},{name:'旅行杯垫',image:'assets/coaster.png'}];
function showPrize(){const prize=prizes[Math.floor(Math.random()*prizes.length)];modal('抽到旅行好礼',prize.name,'再抽一次',showPrize);const box=document.createElement('div');box.className='prize-box';const img=document.createElement('img');img.src=prize.image.replace('assets/','assets/motion/').replace('.png','-original.png');img.alt=prize.name;box.append(img);$('#dialog-content').insertBefore(box,$('#dialog-content p'));const hint=document.createElement('small');hint.className='prize-demo';hint.textContent='互动演示';$('#dialog-content').append(hint)}
const destinations=[{name:'大理·洱海',image:'assets/dali.png'},{name:'延吉·长白山',image:'assets/changbai.png'},{name:'新疆·伊犁',image:'assets/yili.png'}];
const day=()=>new Date().toLocaleDateString('en-CA');let state={points:5,day:day(),counts:[0,0,0,0]};try{const saved=JSON.parse(localStorage.getItem('travel-h5-v1'));if(saved&&Number.isFinite(saved.points)&&Array.isArray(saved.counts))state=saved}catch{}if(state.day!==day()){state.day=day();state.counts=[0,0,0,0]}
function persist(){try{localStorage.setItem('travel-h5-v1',JSON.stringify(state))}catch{}}
const taskNames=['投稿活动笔记且点赞数 ≥ 10','点赞活动笔记','收藏活动笔记','分享活动页面'];const rewards=[5,1,2,1],limits=[1,3,3,1];let selected=0,busy=false,previousFocus,toastTimer;
let shareRevealTimer;
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3000)}
function render(){ $('#task-list').innerHTML=taskNames.map((n,i)=>`<div class="task"><div><strong>${n}</strong><small>完成得${rewards[i]}积分 · 已完成 ${state.counts[i]}/${limits[i]}</small></div><button data-task="${i}" ${state.counts[i]>=limits[i]?'disabled':''}>${state.counts[i]>=limits[i]?'已完成':'去完成'}</button></div>`).join('');$('#balance').textContent=`当前积分：${state.points}`;persist()}
function modal(title,text,button,callback){$('#dialog-content').replaceChildren();const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=text;$('#dialog-content').append(h,p);if(button){const b=document.createElement('button');b.className='primary';b.textContent=button;b.onclick=()=>{ $('#dialog').close();callback?.()};$('#dialog-content').append(b)}if(!$('#dialog').open)$('#dialog').showModal()}
function closeResult(){if(busy)return;clearTimeout(shareRevealTimer);$('#result').hidden=true;document.body.style.overflow='';previousFocus?.focus()}
const tagFrames=[[110,280,860,1165,540,390],[30,230,900,1290,475,340],[10,195,930,1285,443,303]];
function positionCord(){if($('#result').hidden)return;const stage=$('.ticket-stage'),svg=$('#ticket'),frame=tagFrames[selected],r=svg.getBoundingClientRect(),s=stage.getBoundingClientRect(),scale=Math.min(r.width/frame[2],r.height/frame[3]);const x=r.left-s.left+(r.width-frame[2]*scale)/2+(frame[4]-frame[0])*scale,y=r.top-s.top+(r.height-frame[3]*scale)/2+(frame[5]-frame[1])*scale;const cord=$('.hanging-cord');cord.setAttribute('viewBox',`0 0 ${s.width} ${s.height}`);const paths=cord.querySelectorAll('path');paths[0].setAttribute('d',`M${x-8} 0 Q${x-16} ${y*.55} ${x-2} ${y}`);paths[1].setAttribute('d',`M${x+9} 0 Q${x+3} ${y*.55} ${x+2} ${y}`);cord.style.visibility=busy?'hidden':'visible'}
new ResizeObserver(positionCord).observe($('.ticket-stage'));
function draw(){if(busy)return;clearTimeout(shareRevealTimer);busy=true;previousFocus=document.activeElement;$('#result').hidden=false;$('#result').classList.remove('sheet-hidden');$('#result').classList.add('share-pending');$('.share-sheet').inert=true;$('.share-sheet').setAttribute('aria-hidden','true');document.body.style.overflow='hidden';$('#ticket').style.visibility='hidden';$('.hanging-cord').style.visibility='hidden';$('.drawing').hidden=false;$('#again').disabled=true;$('.result-close').focus();setTimeout(()=>{selected=Math.floor(Math.random()*destinations.length);const d=destinations[selected],svg=$('#ticket'),art=$('#ticket-art'),frame=tagFrames[selected];svg.setAttribute('viewBox',frame.slice(0,4).join(' '));svg.setAttribute('aria-label',`你抽到的旅行目的地：${d.name}`);const loader=new Image();loader.onload=()=>{art.setAttribute('width',loader.naturalWidth);art.setAttribute('height',loader.naturalHeight);art.setAttribute('href',d.image);if(selected===0)art.setAttribute('clip-path','url(#dali-outline)');else art.removeAttribute('clip-path');svg.style.visibility='visible';$('.drawing').hidden=true;busy=false;$('#again').disabled=false;positionCord();shareRevealTimer=setTimeout(()=>{if($('#result').hidden)return;$('#result').classList.remove('share-pending');$('.share-sheet').inert=false;$('.share-sheet').removeAttribute('aria-hidden')},650)};loader.onerror=()=>{busy=false;$('#again').disabled=false;$('.drawing').hidden=true;toast('签图加载失败，请重试')};loader.src=d.image},400)}
async function copy(){const url=new URL(location.href);url.hash=`destination-${selected+1}`;try{await navigator.clipboard.writeText(url.href);toast('链接已复制，去聊天窗口粘贴分享')}catch{modal('复制分享链接',url.href,'知道了')}}
async function share(target){const d=destinations[selected];if(navigator.share){try{await navigator.share({title:'把自由写进路上',text:`我抽到了${d.name}，一起出发吧！`,url:location.href});return}catch(e){if(e.name==='AbortError')return}}modal(`分享至${target}`,target==='系统分享'?'当前浏览器不支持系统分享，你可以复制链接或保存签图后发送。':`网页版暂未接入${target}的直达分享。复制链接后打开对应应用粘贴，或保存签图发送给朋友。`,'复制链接',copy)}
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='destination')draw();if(b.dataset.action==='publish')publish(b.dataset.topic);if(b.dataset.action==='lottery')showPrize()});
function publish(topic='把自由写进路上'){modal('带上话题，记录旅行',`发布时带上 #把自由写进路上 #${topic}。当前为互动演示，尚未接入小红书发布接口。`,'复制话题',async()=>{try{await navigator.clipboard.writeText(`#把自由写进路上 #${topic}`);toast('话题已复制')}catch{toast('请手动复制弹窗中的话题')}})}
$('#task-list').onclick=e=>{const b=e.target.closest('[data-task]');if(!b)return;const i=Number(b.dataset.task);if(state.counts[i]>=limits[i])return;modal(taskNames[i],`演示模式：此操作将模拟完成一次任务，增加${rewards[i]}积分；真实任务状态需接入平台核验。`,'模拟完成任务',()=>{if(state.counts[i]>=limits[i])return;state.counts[i]++;state.points+=rewards[i];render();toast(`演示任务已完成，+${rewards[i]}积分`)})};
$('.result-close').onclick=closeResult;$('#close-share').onclick=()=>$('#result').classList.add('sheet-hidden');$('#again').onclick=draw;$('#copy').onclick=copy;$('#save').onclick=()=>{const a=document.createElement('a');a.href=destinations[selected].image;a.download=`旅行签-${destinations[selected].name}.png`;a.click();toast('如未自动下载，可长按签图保存')};$('#topic').onclick=()=>publish();$('#more').onclick=()=>modal('分享你的下一站','可以保存原始签图，或复制本页链接发送给朋友。微信、朋友圈和QQ直接分享需接入平台SDK。','知道了');document.querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>share(b.dataset.share));$('.dialog-close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};document.addEventListener('keydown',e=>{if($('#result').hidden||$('#dialog').open)return;if(e.key==='Escape')closeResult();if(e.key==='Tab'){const list=[...$('#result').querySelectorAll('button')].filter(b=>!b.disabled&&b.getClientRects().length);const a=list[0],z=list[list.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}});render();
